command:
set -e; mkdir -p /config /opt/shoutcast/logs /opt/shoutcast/control /opt/shoutcast/content; : ${MAX_LISTENERS:=128}; : ${STREAM_ID:=1}; : ${STREAM_PATH:=/stream}; : ${PUBLIC_SERVER:=never}; \
cat > /config/sc_serv.conf <<'EOF'
; ---- generated by Runtipi (do not edit inside container) ----
; core
password=${SOURCE_PASSWORD}
adminpassword=${ADMIN_PASSWORD}
portbase=8000
maxuser=${MAX_LISTENERS}
publicserver=${PUBLIC_SERVER}

; files & logs
logfile=/opt/shoutcast/logs/sc_serv.log
w3clog=/opt/shoutcast/logs/sc_w3c.log
banfile=/opt/shoutcast/control/sc_serv.ban
ripfile=/opt/shoutcast/control/sc_serv.rip

; stream #1
requirestreamconfigs=1
streamid_1=${STREAM_ID}
streampath_1=${STREAM_PATH}
streamadminpassword_1=${ADMIN_PASSWORD}
streammaxuser_1=${MAX_LISTENERS}
streamname_1=${STATION_NAME}
streamurl_1=${STATION_URL}
genre_1=${STATION_GENRE}
EOF
[ -n "$SC_USERID" ] && echo "userid=$SC_USERID" >> /config/sc_serv.conf; \
[ -n "$SC_LICENCEID" ] && echo "licenceid=$SC_LICENCEID" >> /config/sc_serv.conf; \
echo 'sc_serv.conf written.'
